    if inspect.isclass(object):
        dottedname = '%s.%s' % (modulename, object.__name__)
        return 'class %s' % dottedname
    if inspect.isfunction(object):
        dottedname = '%s.%s' % (modulename, object.__name__)
        return 'function %s' % dottedname
    return 'object %s' % str(object)


